SELECT s.region, CASE WHEN s.sqft >= 12854 THEN 'high' WHEN s.sqft >= 2823 THEN 'mid' ELSE 'low' END sqft_bucket, COUNT(o.amount) amount_count FROM orders o INNER JOIN customers c ON o.customer_id = c.id LEFT JOIN stores s ON o.store_id = s.id WHERE c.credit_limit > 10700 GROUP BY s.region, CASE WHEN s.sqft >= 12854 THEN 'high' WHEN s.sqft >= 2823 THEN 'mid' ELSE 'low' END HAVING amount_count > 4 ORDER BY amount_count DESC;
